begin;
do $$
declare older uuid;old_order public.lk_orders;a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();g uuid;c uuid;o public.lk_orders;co public.lk_orders;s public.lk_subscriptions;r jsonb;paid_time timestamptz;until_time timestamptz;before_revenue bigint;after_revenue bigint;rev integer;
begin
 insert into auth.users(id,email,email_confirmed_at) values(a,'admin-controls-'||a||'@example.invalid',now()),(u,'buyer-controls-'||u||'@example.invalid',now());
 insert into public.lk_admins(user_id) values(a);
 begin perform public.lk_set_koala_chat(u,false);raise exception 'NON_ADMIN_TOGGLED';exception when others then if sqlerrm<>'ADMIN_REQUIRED' then raise;end if;end;
 select revision into rev from public.lk_site_settings where id='public';
 perform public.lk_set_koala_chat(a,false);perform public.lk_set_koala_chat(a,false);
 if (select (data#>>'{features,koala_chat}')::boolean from public.lk_site_settings where id='public') is distinct from false then raise exception 'CHAT_NOT_DISABLED';end if;
 if (select count(*) from public.lk_admin_audit where admin_id=a and action='koala_chat_toggled')<>1 then raise exception 'TOGGLE_NOT_IDEMPOTENT';end if;
 perform public.lk_set_koala_chat(a,true);
 insert into public.lk_gifts(edit_token_hash,owner_user_id,format,plan_id,content,public_consent) values(repeat('a',64),u,'album','carinho','{"sender":"Teste","recipient":"24h","letter":"Sintético"}',true) returning id into g;
 perform public.lk_add_photo(g,g::text||'/test.png');
 o:=public.lk_prepare_order_v2(g,'carinho','mercosulpay',gen_random_uuid(),'once');update public.lk_orders set provider_id='fixture-'||o.id,status='pending' where id=o.id;
 begin perform public.lk_admin_approve_order(u,o.id,'Extrato sintético conferido',o.amount_cents);raise exception 'NON_ADMIN_APPROVED';exception when others then if sqlerrm<>'ADMIN_REQUIRED' then raise;end if;end;
 begin perform public.lk_admin_approve_order(a,o.id,'curto',o.amount_cents);raise exception 'NO_REASON_APPROVED';exception when others then if sqlerrm<>'APPROVAL_INVALID' then raise;end if;end;
 begin perform public.lk_admin_approve_order(a,o.id,'Extrato sintético conferido',o.amount_cents+1);raise exception 'WRONG_AMOUNT_APPROVED';exception when others then if sqlerrm<>'APPROVAL_CONFLICT' then raise;end if;end;
 select coalesce(sum(amount_cents),0) into before_revenue from public.lk_financial_ledger() where approval_source='manual';
 perform public.lk_admin_approve_order(a,o.id,'Extrato sintético conferido',o.amount_cents);
 select paid_at,expires_at into paid_time,until_time from public.lk_gifts where id=g;
 if until_time<>paid_time+interval '24 hours' or (select edit_expires_at from public.lk_gifts where id=g)<>until_time then raise exception 'WRONG_24H_ACCESS';end if;
 if not exists(select 1 from public.lk_orders where id=o.id and status='paid' and approval_source='manual' and provider_verified_at is null and manual_approved_by=a and manual_approval_reason='Extrato sintético conferido') then raise exception 'MANUAL_PROVENANCE_MISSING';end if;
 r:=public.lk_admin_approve_order(a,o.id,'Repetição sintética',o.amount_cents);
 if r->>'already_approved'<>'true' or (select paid_at from public.lk_gifts where id=g)<>paid_time or (select count(*) from public.lk_admin_audit where action='payment_manually_approved' and target=o.id::text)<>1 then raise exception 'DOUBLE_GRANT';end if;
 select coalesce(sum(amount_cents),0) into after_revenue from public.lk_financial_ledger() where approval_source='manual';
 if after_revenue-before_revenue<>o.amount_cents then raise exception 'MANUAL_LEDGER_MISMATCH';end if;
 r:=public.lk_captain_report(extract(year from now() at time zone 'America/Sao_Paulo')::integer,extract(month from now() at time zone 'America/Sao_Paulo')::integer);
 if not exists(select 1 from jsonb_array_elements(r->'by_approval_source') x where x->>'approval_source'='manual') then raise exception 'REPORT_SOURCE_MISSING';end if;
 perform public.lk_verify_manual_order(o.id);perform public.lk_verify_manual_order(o.id);
 if (select approval_source from public.lk_orders where id=o.id)<>'provider' or (select manual_approved_by from public.lk_orders where id=o.id)<>a or (select expires_at from public.lk_gifts where id=g)<>until_time then raise exception 'PROVIDER_RECONFIRM_CHANGED_ACCESS';end if;
 perform public.lk_publish(g,'controls-'||g);
 -- Monthly grants use the same allocation rules and do not create an external subscription.
 insert into public.lk_gifts(edit_token_hash,owner_user_id,format,plan_id,content,public_consent) values(repeat('b',64),u,'ambos','universo','{"sender":"Teste","recipient":"Clube","letter":"Sintético"}',true) returning id into c;
 update public.lk_gifts set content=content||jsonb_build_object('email','buyer-controls-'||u||'@example.invalid') where id=c;
 perform public.lk_add_photo(c,c::text||'/club.png');co:=public.lk_prepare_order_v2(c,'universo','stripe',gen_random_uuid(),'monthly');update public.lk_orders set provider_id='fixture-'||co.id,status='pending' where id=co.id;
 select coalesce(sum(amount_cents),0) into before_revenue from public.lk_financial_ledger() where approval_source='manual';
 perform public.lk_admin_approve_order(a,co.id,'Conferência sintética do ciclo',co.amount_cents);perform public.lk_admin_approve_order(a,co.id,'Conferência sintética do ciclo',co.amount_cents);
 insert into public.lk_gifts(edit_token_hash,owner_user_id,format,plan_id,content,checkout_email) values(repeat('c',64),u,'album','universo',jsonb_build_object('email','buyer-controls-'||u||'@example.invalid'),'buyer-controls-'||u||'@example.invalid') returning id into older;
 insert into public.lk_orders(gift_id,request_id,provider,provider_id,plan_id,amount_cents,billing_cycle,status) values(older,gen_random_uuid(),'stripe','old-club-'||older,'universo',co.amount_cents,'monthly','failed') returning * into old_order;
 begin perform public.lk_admin_approve_order(a,old_order.id,'Pedido antigo não pode criar outro Clube',old_order.amount_cents);raise exception 'SECOND_CLUB_MANUALLY_APPROVED';exception when others then if sqlerrm<>'APPROVAL_CONFLICT' then raise;end if;end;
 select * into s from public.lk_subscriptions where gift_id=c;
 if s.auto_renew or s.provider_subscription_id is not null or public.lk_club_balance(u)->>'remaining'<>'1' then raise exception 'CLUB_GRANT_WRONG';end if;
 select coalesce(sum(amount_cents),0) into after_revenue from public.lk_financial_ledger() where approval_source='manual';
 if after_revenue-before_revenue<>co.amount_cents then raise exception 'CLUB_RECEIPT_DOUBLE_COUNT';end if;
 perform public.lk_verify_manual_order(co.id);
 perform public.lk_apply_stripe_cycle(c,'fixture-sub-'||co.id,'active',s.period_start-interval '5 days',s.period_end-interval '5 days',co.amount_cents,'fixture-invoice-'||co.id,true,false,true);
 if (select count(*) from public.lk_club_periods where subscription_id=s.id)<>1 or public.lk_club_balance(u)->>'remaining'<>'1' then raise exception 'LATE_PROVIDER_DOUBLE_QUOTA';end if;
 update public.lk_orders set status='refunded' where id=o.id;
 begin perform public.lk_admin_approve_order(a,o.id,'Pedido reembolsado sintético',o.amount_cents);raise exception 'REFUNDED_APPROVED';exception when others then if sqlerrm<>'APPROVAL_INVALID' then raise;end if;end;
 update public.lk_profiles set disabled=true where id=a;
 begin perform public.lk_set_koala_chat(a,false);raise exception 'DISABLED_ADMIN_TOGGLED';exception when others then if sqlerrm<>'ADMIN_REQUIRED' then raise;end if;end;
 if has_function_privilege('anon','public.lk_set_koala_chat(uuid,boolean)','EXECUTE') or has_function_privilege('authenticated','public.lk_admin_approve_order(uuid,uuid,text,integer)','EXECUTE') or has_function_privilege('authenticated','public.lk_verify_manual_order(uuid)','EXECUTE') or has_function_privilege('anon','public.lk_financial_ledger()','EXECUTE') then raise exception 'ADMIN_RPC_PUBLIC';end if;
end $$;
select 'PASS: admin toggle, permissions, amount/reason, manual provenance, exact 24h, replay, publication, reports, monthly quota and late provider confirmation' as result;
rollback;
